from pathlib import Path
import re, ast, os, subprocess
root=Path('.')
out=root/'PROJECT_DOCUMENTATION'; out.mkdir(exist_ok=True)
# inventory, route decorators, ORM model declarations, env variable names
ignored={'.git','.venv','node_modules','__pycache__','instance','logs','tmp'}
files=[Path(x) for x in subprocess.check_output(['git','ls-files','-co','--exclude-standard'],text=True).splitlines() if Path(x).is_file() and Path(x).parts[0] != 'PROJECT_DOCUMENTATION']
route_rows=[]
for p in files:
 if p.suffix!='.py': continue
 try: txt=p.read_text(encoding='utf-8',errors='ignore')
 except: continue
 lines=txt.splitlines()
 for i,line in enumerate(lines):
  if re.search(r'@\w+(?:\.\w+)*\.(?:route|get|post|put|patch|delete)\(',line):
   block=line.strip()
   j=i+1
   while j<len(lines) and j<i+6 and ')' not in block:
    block+=' '+lines[j].strip(); j+=1
   func=''
   for k in range(j,len(lines)):
    m=re.match(r'\s*(?:async\s+)?def\s+(\w+)\(',lines[k])
    if m: func=m.group(1);break
    if k>j+3:break
   route_rows.append((p.as_posix(),i+1,block,func))
model_rows=[]
for p in (root/'backend/models').rglob('*.py'):
 try: tree=ast.parse(p.read_text(encoding='utf-8',errors='ignore'))
 except: continue
 for node in ast.walk(tree):
  if isinstance(node,ast.ClassDef):
   bases=[ast.unparse(x) for x in node.bases]
   if not any('Model' in b for b in bases): continue
   table=node.name
   fields=[]
   for n in node.body:
    if isinstance(n,(ast.Assign,ast.AnnAssign)):
     targets=n.targets if isinstance(n,ast.Assign) else [n.target]
     val=n.value
     if val and isinstance(val,ast.Call) and 'Column' in ast.unparse(val.func):
      for t in targets:
       if isinstance(t,ast.Name):
        typ=ast.unparse(val.args[0]) if val.args else 'unspecified'
        fields.append(f'{t.id} ({typ})')
      if val.args and isinstance(val.args[0],ast.Constant) and isinstance(val.args[0].value,str): table=val.args[0].value
   model_rows.append((p.as_posix(),node.name,table,fields))
env=[]
for l in (root/'.env.example').read_text(errors='ignore').splitlines():
 m=re.match(r'^([A-Z][A-Z0-9_]*)=',l)
 if m: env.append(m.group(1))
# route appendix grouped by source file; raw decorators are exact evidence and no prefix assumptions
route_md='## Route decorator inventory (repository source paths)\n\nThis generated appendix lists route decorators found in Python source. Paths inside Blueprints may receive additional prefixes at registration. `app.url_map` at runtime is authoritative for effective URLs. This inventory is source level and does not certify endpoint health.\n\n'
for f in sorted(set(r[0] for r in route_rows)):
 route_md+='### `'+f+'`\n\n'
 for fn,ln,dec,func in [r for r in route_rows if r[0]==f]: route_md+=f'- Line {ln}: `{dec}` → `{func or "handler name not found"}`\n'
 route_md+='\n'
models_md='## SQLAlchemy model inventory extracted from `backend/models/`\n\nFields below are the declarations found on model classes; inherited fields, relationships, constraints, runtime migrations and dynamically created columns may not appear. See each source file for authoritative definitions.\n\n'
for f,cls,table,fields in model_rows:
 models_md+=f'### `{cls}` (table `{table}`)\n- Source: `{f}`\n- Declared columns: '+(', '.join(f'`{x}`' for x in fields) if fields else 'No direct `db.Column` declarations found (may inherit fields or use another pattern).')+'\n\n'
structure='\n'.join(f'- `{p.name}/` — {sum(1 for x in files if x.is_relative_to(p))} tracked-like files in this directory tree.' for p in sorted([x for x in root.iterdir() if x.is_dir() and x.name not in ignored and x.name!='PROJECT_DOCUMENTATION'],key=lambda q:q.name.lower()))
# Common verified documentation content
overview='''# Project Overview\n\n## What AgroZen is\nAgroZen is a multi-page agricultural web application. Its main server is Python/Flask (`app.py`). The browser uses HTML, CSS and JavaScript. The server connects agricultural pages, model inference, database-backed services, authentication, background jobs and external integrations. The repository contains a wide set of feature modules; their presence in source does not prove every one is operational in a deployed environment.\n\n## Purpose\nThe product brings crop decision support and related farmer services into one web entry point. Main areas include crop recommendation, fertilizer advice, yield estimation, plant disease classification/advisory, weather and climate information, irrigation, crop rotation, market prices, marketplace, community and operational services. Advice should be treated as decision support and verified locally.\n\n## Technology stack (verified in source/config)\n- Frontend: standalone HTML pages, CSS stylesheets, browser JavaScript; no main React/Vue/Angular application found. `package.json` describes a separate Express chatbot server.\n- Backend: Python 3 application, Flask, Flask Blueprints; optional Node.js/Express service in `server.js`.\n- Database: Flask-SQLAlchemy ORM and Flask-Migrate/Alembic; development config defaults to SQLite; `DATABASE_URL` can change it.\n- Authentication: project has more than one auth path: `backend.api.v1.auth` routes and legacy `auth_utils.py` JWT decorators. Some API handlers use Flask-JWT-Extended. Inspect each endpoint’s decorator; do not assume uniform protection. Password hashing uses Werkzeug in the User model.\n- Async/realtime: Celery, Redis configuration, Flask-SocketIO event handlers. Workers/brokers must actually run.\n- ML/data: PyTorch, TensorFlow/Keras, scikit-learn, XGBoost/CatBoost, pandas/numpy/joblib and image tooling appear in requirements and modules. Specific models are feature-specific.\n- Integrations: Firebase configuration, Gemini, SMTP, weather/FX/translation APIs, optional S3 and messaging credentials are represented in configuration. Availability depends on credentials/network.\n- Tests: pytest configuration and Python test directories; security-related tests also exist.\n- Deployment: Dockerfile and docker-compose for Flask, Redis, MailHog, Celery. GitHub Actions workflows are mostly repository automation; no verified production hosting target found.\n\n## Entry points\n- Main Flask server: `app.py`; README instructs `python app.py`.\n- Optional Node server: `server.js`; `npm start` launches it. It is not the primary Flask app.\n- Main homepage: `/` serves root `index.html`.\n\n## Feature status rules\nThe `ENABLE_*` settings are defined in `backend/config/settings.py`, but code search found no feature consumer beyond their definitions; treat them as currently non-operative configuration. Disease API Blueprints are registered under API v1; the old `disease_prediction.routes` import in `app.py` is commented and the file was not found. Some routes require trained model artifacts, external credentials, queue services or DB models.\n\n## Repository facts\nThis scan found 822 files after excluding virtual environment, dependency, runtime database/log/temp, notebook, and large model artifacts. The repository has many feature directories and duplicate/legacy interfaces. Use the folder guide and route appendix to navigate; this documentation prioritizes application-owned code over generated dependencies and data artifacts.\n'''
structure_doc=f'''# Project Structure\n\n## Top-level directory inventory\n\n{structure}\n\n## Important files\n- `app.py` — Flask app factory-like bootstrap at module scope: configuration, extension setup, Blueprint registration, direct routes, error handlers and Socket.IO startup.\n- `backend/` — primary backend packages: API modules, auth, config, docs, extensions, middleware, models, ML, monitoring, schemas, services, sockets, tasks, tests and utilities.\n- `templates/` — Flask-rendered templates, including the yield prediction page.\n- Root `*.html`, `*.css`, `*.js` — multi-page web UI and feature scripts.\n- `requirements.txt` — Python dependency declarations. It includes application, ML, testing and utility packages.\n- `package.json`, `package-lock.json` — optional Node/Express chatbot service and npm dependency lock.\n- `server.js` — optional Node server entry point.\n- `migrations/` — Alembic/Flask-Migrate revisions.\n- `docker-compose.yml`, `Dockerfile` — local multi-service container setup.\n- `.env.example` — variable names/placeholders; actual `.env` is private and intentionally not read for documentation.\n- `.github/workflows/` — issue/PR automation; workflows should not be mistaken for app deployment.\n- `README.md` — setup and high-level architecture, checked against source.\n- `pytest.ini`, `tests/`, `backend/tests/` — test configuration and suites.\n\n## Reading strategy\nStart at `app.py`, follow its `register_blueprint` calls into `backend/api/v1/__init__.py`, then follow a route into the feature service and models. For browser journeys, follow a page’s `<script>` reference and search JavaScript for `fetch`, form action, or URL. A Blueprint-local route prefix is combined with registration prefixes; runtime `app.url_map` is the definitive path list.\n\n## Duplication and legacy areas\nThe project contains similarly named root pages and feature directories, legacy URLs, standalone model/training notebooks, and both legacy and versioned API modules. Some model scripts are experiments, not loaded production paths. Confirm imports from `app.py` before assuming a file is live.\n'''
architecture='''# System Architecture\n\n## Simple picture\nA browser page sends a request to Flask. Flask routes it to a feature handler. The handler validates input, calls business logic, may query SQLAlchemy, run a model or call an outside service, then returns HTML/JSON. Long jobs can be sent to Celery through Redis; Socket.IO can deliver live events.\n\n```mermaid\nflowchart LR\n U[Farmer / buyer / admin] --> UI[HTML CSS JavaScript pages]\n UI -->|HTTP form or fetch| F[Flask app.py]\n F --> BP[Registered Blueprints and direct routes]\n BP --> S[Services and domain utilities]\n S --> ML[ML models where artifacts exist]\n S --> DB[(SQL database via SQLAlchemy)]\n S --> EXT[External APIs: optional credentials]\n BP --> Q[Celery task queue]\n Q --> R[(Redis broker/result backend)]\n Q --> W[Celery worker]\n W --> DB\n F --> UI\n F --> WS[Socket.IO events where configured]\n```\n\n## Frontend\nThe primary UI is multi-page HTML/CSS/JS, not a detected React SPA. Pages serve as entry points; JavaScript handles interactions and fetches where implemented. Root static serving and Flask rendering coexist. `templates/` is a Flask template folder, while many pages live at repository root.\n\n## Backend and API design\n`app.py` initializes Flask, loads configuration, initializes extensions, registers direct handlers and Blueprints, then starts Socket.IO. API v1 is a parent Blueprint with many feature Blueprints. Smaller modules isolate routes by domain. Some domain services may also be imported by separate pages or services. The project has both synchronous form routes and JSON API routes.\n\n## Database\nFlask-SQLAlchemy maps Python model classes to relational tables. Flask-Migrate records schema evolution. Development defaults to SQLite; environment configuration can use a different database. `db.create_all()` is called at startup in `app.py`, while migrations also exist; deployment practices should choose a controlled migration flow. Model inventory is in `06_Database_Documentation.md`.\n\n## Integrations and deployment dependencies\nGemini, Firebase, SMTP, weather, FX, translation, S3, Redis and messaging settings are configurable. A credential name in `.env.example` means a possible integration, not a successful connection. Docker Compose includes Flask, Redis, MailHog and Celery worker. Production WSGI/hosting setup was not verified in repository configuration.\n\n## Example synchronous sequence\n```mermaid\nsequenceDiagram\n participant B as Browser\n participant F as Flask route\n participant V as Validation\n participant S as Feature service\n participant M as Model or DB\n B->>F: POST form / JSON\n F->>V: Check required fields and types\n V-->>F: Valid input\n F->>S: Call feature logic\n S->>M: Predict / query / persist\n M-->>S: Result\n S-->>F: Domain result\n F-->>B: HTML or JSON response\n```\n\n## Async sequence\n```mermaid\nsequenceDiagram\n participant B as Browser\n participant F as Flask\n participant Q as Redis/Celery broker\n participant W as Worker\n B->>F: Submit long task\n F->>Q: enqueue task\n F-->>B: 202 + task_id\n Q->>W: deliver task\n W->>W: compute and store result\n B->>F: GET status(task_id)\n F-->>B: pending / processing / completed / failed\n```\n'''
frontend='''# Frontend Documentation\n\n## Framework and entry points\nThe main frontend is plain HTML, CSS and browser JavaScript. No root package script builds a frontend bundle. `/` serves root `index.html`; other direct Flask paths serve feature pages. `templates/` contains server-rendered pages such as `yield_prediction.html`. `server.js` is a separate Express/Socket.IO-oriented option, not proof of a frontend framework.\n\n## Page families\nRoot files include home/navigation, login/register/reset, crop, disease, yield, fertilizer, weather, dashboards, marketplace, forum, equipment, finance, government schemes, logistics, sustainability and service portals. Specific scripts typically match page names (for example `disease.html` and `disease.js`). Directories such as `src/`, `frontend/`, `static/`, `styles/`, `css/`, `js/`, and `javascript/` are present, but overlapping names mean verify which files are actually linked by the target HTML.\n\n## Components, state and routing\nThere is no verified React component hierarchy, props system, Redux/Zustand store or React Router. Each page owns its DOM and page script. State may be in JS variables, browser localStorage, session/auth mechanisms, or server responses. Navigation is mostly links and direct routes. `disease.js`, for example, tracks selected file and prediction history in localStorage.\n\n## Forms and API calls\nPages use HTML forms and JavaScript event listeners. Requests can be standard form posts (server returns HTML) or `fetch` calls (typically JSON). For any UI control, trace: input element → event listener → validation/serialization → URL/method → response parsing → DOM update. Client validation is usability only; backend validation is required.\n\n## Authentication UI\n`login.html`, `register.html`, `auth.js` and backend auth routes exist. The repository contains multiple auth approaches; inspect the actual page script to learn whether it attaches Bearer tokens, uses cookies or uses Firebase. Do not say all pages are protected; backend decorator coverage differs by endpoint. `reset-password.html` is served by a page route, but token correctness and password-reset backend workflow must be confirmed in the auth module.\n\n## Loading, error and responsive behavior\nSome scripts explicitly show loading states and inline errors (disease analysis is one example); this pattern is not guaranteed across every page. CSS files provide layouts and breakpoints, but a global design system/component framework was not detected. Confirm at target viewport sizes and inspect each page’s script for error paths.\n\n## No inferred components\nA page name does not establish a reusable component or complete backend integration. The source should be traced before documenting a frontend/backend contract. The disease classifier flow is: image selected → client downscales to <=1600px edge and JPEG → POST base64 JSON to `/api/v1/ai-disease/predict-trained` → display candidate / uncertainty and history.\n'''
backend_doc='''# Backend Documentation\n\n## Startup\n`app.py` loads `.env`, imports extension and feature modules, builds the Flask app, applies a selected config, sets upload storage, initializes SQLAlchemy, migrations, mail and limiter, configures Celery and audit middleware, imports models, configures CORS, registers Blueprints, initializes Socket.IO, cache and Babel, creates tables in app context, then configures Gemini. Note: startup currently raises if `GEMINI_API_KEY` is absent outside testing; this is an operational coupling to an external key and should be considered when running locally.\n\n## Layers\n- Routes/controllers: Flask route functions and Blueprint modules accept HTTP requests and choose response codes/forms.\n- Validation/schemas: Marshmallow schemas and validation utilities check incoming data; coverage varies.\n- Services/domain logic: `backend/services/`, `agri_utils.py`, `server/Routes/`, and feature packages implement actions.\n- Models: `backend/models/` defines ORM entities.\n- Middleware: audit, CORS, rate limiting and auth decorators.\n- Async/realtime: Celery tasks and Socket.IO event handlers.\n\n## Main direct routes\n`app.py` directly defines page-serving routes, Firebase config, task status, async crop, fertilizer, loan/report endpoints, yield prediction, reset-password/static catch-all, rotation alias and error handlers. See complete decorator appendix in `08_API_Documentation.md`.\n\n## API families\n`backend/api/v1/__init__.py` registers a large set of versioned APIs for auth, tasks, assets/files, forum, pools, market, risk, schemes, weather, traceability, disease, insurance, farm, advisory, sustainability, procurement, irrigation, soil, climate, labor, logistics, audit, finance, carbon, warehouse and more. API v1 itself is mounted by `backend/api/__init__.py`. Endpoint specifics remain in each route module.\n\n## Request and response lifecycle\n```mermaid\nflowchart TD\n R[HTTP request] --> CORS[CORS / WSGI / Flask dispatch]\n CORS --> AUTH{Route has auth decorator?}\n AUTH -->|yes| TOKEN[Verify token and role]\n AUTH -->|no| VALID[Parse and validate request]\n TOKEN --> VALID\n VALID --> HANDLER[Route handler]\n HANDLER --> SERVICE[Business service / domain utility]\n SERVICE --> DB[(SQLAlchemy database)]\n SERVICE --> MODEL[ML model or external API when configured]\n DB --> FORMAT[Build safe result]\n MODEL --> FORMAT\n FORMAT --> RESP[HTML / JSON / file / error]\n RESP --> CLIENT[Browser]\n```\n\n## Validation, errors and logging\nSome routes perform manual required-field and range checks; schemas/utilities exist elsewhere. Flask has global 404 handling and logging. Error handling is not uniform: several routes catch broad exceptions and return message text. Production should avoid exposing exception details. Transactions should rollback after DB failures.\n\n## Uploads and storage\nAn upload folder is configured by `app.py`; config supports local/S3 settings. File API and ingestion Blueprints exist. Confirm each endpoint’s limits, safe filename handling, authorization, content validation and ownership check before claiming secure upload behavior.\n\n## Feature flags and disabled paths\n`FeatureFlags` fields exist, but source search found no callers reading them. Their environment values do not currently appear to gate routes. The old disease import path referenced in a commented line does not exist; disease APIs are registered via API v1. Crop inference can be unavailable if its model/encoder artifacts are absent.\n'''
database_doc='''# Database Documentation\n\n## Technology and connection\nFlask-SQLAlchemy is the ORM; Flask-Migrate/Alembic handles schema revisions. `backend/config/settings.py` defaults to SQLite for development and reads `DATABASE_URL`/`DEV_DATABASE_URL`. The active environment may override this. The repository also contains `instance/AgroZen_dev.db`; documentation does not inspect or disclose user data.\n\n## How ORM persistence works\nA route or service queries model classes, constructs/updates objects, calls `db.session.add`, then `commit`. A failed transaction should call `rollback`. SQLAlchemy generates parameterized SQL. Migrations should be applied deliberately in deployments; `db.create_all()` at application startup does not replace schema migration management.\n\n## Models and schema\nThe following per-model inventory is extracted from direct `db.Column` declarations in `backend/models/`. Relationships, inherited fields, constraints, indexes and migration-only details are not fully inferable from that summary; inspect each source and migration.\n\n'''+models_md+'''\n## Relationship and ER overview (conceptual)\n```mermaid\nerDiagram\n USER ||--o{ FILE : owns\n USER ||--o{ NOTIFICATION : receives\n USER ||--o{ AUDIT_LOG : performs\n USER ||--o{ PREDICTION_HISTORY : creates\n FARM ||--o{ FARM_MEMBER : includes\n FARM ||--o{ FARM_ASSET : contains\n EQUIPMENT ||--o{ RENTAL_BOOKING : booked\n FORUM_THREAD ||--o{ POST_COMMENT : has\n SUPPLY_BATCH ||--o{ CUSTODY_LOG : tracks\n```\nThis is a conceptual relationship map of common model families; validate actual foreign key declarations in model source before treating every line as a guaranteed relationship.\n\n## Transactions, indexes and seeds\nCommit/rollback patterns appear in services. Unique fields and indexes are declared model-by-model; no single schema manifest or comprehensive seed command was verified. No global transaction diagram should be inferred beyond each endpoint’s actual writes.\n\n## API to database mapping\nThe user model is used by auth; file metadata and user relations are represented in core models; disease incidents and outbreak zones use disease models; market, soil, irrigation, farm and finance routes use their matching model families. A route may be read-only or may not persist its result. Confirm the handler/service calls before asserting writes.\n'''
auth='''# Authentication and Authorization\n\n## Important: multiple mechanisms exist\nThe repository contains legacy JWT helpers (`auth_utils.py`), a versioned auth Blueprint (`backend/api/v1/auth.py` using `AuthService`), and some routes using Flask-JWT-Extended decorators. Authentication is not one uniform global system. Trace a specific endpoint to know which token and decorator it accepts.\n\n## Registration\nThe versioned auth route is mounted below `/api/v1/auth`. It accepts username, email and password; checks required values, enforces a Gmail suffix, checks duplicates, creates a `User`, stores a Werkzeug password hash, commits, sends a verification email and logs an audit event. Mail delivery depends on SMTP config. The `User` model also enforces Gmail and name-character constraints. Password minimum/complexity policy must be checked in the actual service and should be strengthened if absent.\n\n## Login and token lifecycle\n`backend/api/v1/auth.py` defines login and related auth endpoints. `AuthService` performs account behavior; `auth_utils.py` separately encodes/decodes JWT with HS256 and provides `token_required` / `roles_required`. Some login implementations may return access tokens and refresh cookies; verify exact handler and frontend usage before making security claims. Do not store or display token values.\n\n```mermaid\nsequenceDiagram\n participant U as User\n participant UI as Login form\n participant A as Auth route/service\n participant DB as User table\n U->>UI: enter email/name and password\n UI->>A: POST credentials over HTTPS in deployment\n A->>DB: find account\n DB-->>A: stored password hash and role\n A->>A: verify password hash; issue token if valid\n A-->>UI: success/token or error\n UI->>A: protected request with accepted token\n A->>A: validate signature, expiry, identity and role\n A-->>UI: protected data or 401/403\n```\n\n## Password reset and logout\nThe UI route `/reset-password/<token>` serves `reset-password.html`; this proves a page exists, not that a complete secure reset-token issuance and one-time consumption path is active. Search the auth service and verify expiration, single-use semantics and email validation before presenting it as complete. Logout/revocation behavior depends on which token path is used.\n\n## Authorization\nAuthentication answers “who are you?”; authorization answers “may you do this?” Role guards in `auth_utils.py` accept role lists. Other modules use `jwt_required`. A User role field does not automatically protect routes. Audit all write/admin/file routes for explicit authorization and ownership checks.\n\n## Security findings and improvements\n- `auth_utils.py` contains a development fallback JWT secret; deployments must require a long unique secret and fail closed.\n- Some APIs use different JWT implementations; standardize issuer, audience, expiry, refresh, revocation and error behavior.\n- Cookie refresh tokens need Secure, HttpOnly, SameSite and CSRF review.\n- Gmail-only validation is product-specific and excludes other valid users.\n- Ensure account enumeration and password reset responses do not reveal sensitive state.\n'''
api='''# API Documentation\n\n## How to read endpoints\nMethods and paths are exact only when verified in decorators and Blueprint registration. API v1 is mounted at `/api/v1`; child prefixes compose with route strings. Parameters vary by endpoint. The source route appendix below is generated from all Python route decorators in scanned project files and links each to its source line. It includes standalone sub-apps too, so not every endpoint is served by the main `app.py`.\n\n## Important main-server journeys\n| Method | Effective endpoint | Purpose / inputs | Auth / result notes |\n|---|---|---|---|\n| GET | `/` | Main UI (`index.html`) | HTML page |\n| GET | `/farmer`, `/shopkeeper`, `/main`, `/about`, `/blog`, `/contact`, `/chat` | Serve named root pages | HTML |\n| GET | `/yield/` | Yield form with trained model choices | 503 if required artifact missing |\n| POST | `/yield/predict` | Form values: crop, season, state, year, area, rainfall, fertilizer, pesticide | Server renders result; 400 invalid fields |\n| GET/POST | `/crop/`, `/crop/predict` | Crop form and recommendation | Crop blueprint under `/crop`; model/encoder artifacts required |\n| POST | `/api/crop/predict-async` | N,P,K,temperature,humidity,pH,rainfall | JWT and farmer/admin/consultant; 202 response with task ID |\n| GET | `/api/task/<task_id>` | Celery status/result | JWT protected |\n| POST | `/api/recommend/fertilizer` | soil_ph, crop_type, optional growth_stage/recent_weather | JWT role guard; JSON recommendation |\n| POST | `/api/v1/ai-disease/predict-trained` | base64 image, optional crop_type | Public with rate limit; classifier result or 400/503/500 |\n| POST | `/api/v1/ai-disease/analyze` | image, crop_type, optional location/coordinates | token_required; performs advisory and saves incident |\n| GET | `/api/v1/ai-disease/history` | optional crop_type, days | token_required; user history |\n| GET | `/api/v1/ai-disease/treatment` | crop_type, disease_name | no auth decorator visible; treatment response |\n| POST/GET | `/api/v1/disease/incidents` | disease/crop/severity/symptoms/coordinates; GET supports filters | Flask-JWT-Extended protected |\n| GET | `/api/firebase-config` | no body | rate limited; returns public Firebase client config keys, not private service credentials |\n\nThese examples are not a substitute for the code contract. Use each route’s schema/docstring and implementation for exact required fields and response variants.\n\n## Request/response example: trained disease classifier\nRequest: `POST /api/v1/ai-disease/predict-trained`, JSON `{ "image": "<base64 or data URL>", "crop_type": "Tomato" }`. Success: `{ "status":"success", "prediction": { "class_name":"...", "crop":"...", "disease":"...", "confidence":0, "alternatives":[...], "model":"...", "device":"..." } }`. Scores are raw softmax outputs, not calibrated probabilities. Error cases include missing/invalid image (400), missing model artifact (503) and inference failure (500).\n\n## Authentication and response convention\nSome endpoints return JSON with `status`, `message`, `data` or `error`; HTML forms return a rendered template. Error status codes are not globally uniform. `Authorization` requirements are route-specific.\n\n'''+route_md
workflows='''# Application Workflows\n\n## Crop recommendation (synchronous)\n1. Farmer opens crop page and enters soil/climate values.\n2. Browser posts form values to `/crop/predict`.\n3. Crop route requires N, P, K, temperature, humidity, pH and rainfall; it converts and range-checks numeric values.\n4. Route uses model and label encoder loaded from model-versioning manager or legacy pickle files.\n5. It predicts crop label and renders result template with input parameters/model version. Missing model returns unavailable error; invalid values return form with error.\n\n```mermaid\nsequenceDiagram\n participant F as Farmer\n participant P as Crop page\n participant R as /crop/predict\n participant M as Loaded crop model\n F->>P: enter soil/weather data\n P->>R: POST form\n R->>R: validate required fields and ranges\n R->>M: predict ordered features\n M-->>R: encoded or text crop label\n R->>R: decode label if needed\n R-->>P: render result or validation error\n```\n\n## Yield prediction\nGET `/yield/` asks the initialized YieldPredictionService for valid crop/season/state choices and renders `yield_prediction.html`. At startup the service looks for a joblib bundle containing model, encoders, scaler and feature schema. POST `/yield/predict` validates numbers/categories, encodes categories, arranges feature columns, scales as trained and predicts; missing bundle returns 503, invalid form returns 400 and unexpected error logs then shows generic failure.\n\n## Disease image workflow\n`disease.html`/`disease.js` reads selected photo, creates a resized JPEG data URL and POSTs to `/api/v1/ai-disease/predict-trained`. Server verifies base64, size and supported crop, converts image to RGB 256x256 tensor, applies same [0,1] preprocessing used by its notebook, gets CNN logits, applies softmax and returns top prediction/alternatives. UI now gates low/ambiguous raw scores as uncertain; it does not certify disease. Authenticated `/analyze` is a separate service path that may save a diagnosis; incident reporting is another API.\n\n## Fertilizer, irrigation and rotation\nFertilizer: authenticated role-restricted JSON POST to `/api/recommend/fertilizer` → parse soil pH/crop/stage/weather → `agri_utils.recommend_fertilizer` → JSON. Irrigation and rotation use separate Blueprints under server Routes. Their input/output contracts are endpoint specific; there is no assumed automatic pipeline from crop recommendation.\n\n## Authentication\nRegistration/login forms send credentials to auth routes; service checks account and hash, persistence writes user metadata and route returns result/tokens. Protected calls are decorated; failed/missing token gets an auth error. Role checks further limit actions. Frontend token storage varies and should be traced in `auth.js`.\n\n## Async task\nCrop task route authenticates/authorizes, checks required fields, enqueues Celery task, returns 202/task ID. The browser polls status route. Worker computes and state is surfaced as pending, processing, completed/result or failed. Redis and worker availability are required.\n\n## Market prices and other services\nPrice tracker Blueprint includes market/state lookup, forecast, profit optimization, heatmap and alert subscription. Trace each specific page to route and service before assuming data freshness, persistence or external provider. API v1 includes many additional module families; route appendix is a navigation index, not a claim that all are production ready.\n'''
config_doc='''# Setup and Installation\n\n## Requirements and install\nREADME documents Python virtual environment and requirements installation. On Windows PowerShell from project root:\n```powershell\npy -m venv .venv\n.\\.venv\\Scripts\\Activate.ps1\npython -m pip install --upgrade pip\npython -m pip install -r requirements.txt\nif (-not (Test-Path .env)) { Copy-Item .env.example .env }\n```\nEdit `.env` locally using only credentials for desired services. Never share or commit it. README says `GEMINI_API_KEY` is required by normal app startup; testing mode supplies a test placeholder.\n\n## Run the main app\n```powershell\npython app.py\n```\nOpen `http://127.0.0.1:5000/`; health route is documented in README. `app.py` starts Socket.IO. The main frontend is served by Flask, so a separate frontend build is not needed.\n\n## Optional services\n```powershell\ndocker compose up --build\n```\nCompose defines Redis, MailHog, Flask and Celery worker. Ensure `.env` is configured. Optional Node service: `npm install`, then `npm start` or `npm run dev`; this starts `server.js`, not Flask.\n\n## Tests\n`pytest.ini` configures pytest paths including `tests/` and backend suites. Run `python -m pytest` from root. This is a repository command reference; tests were not run as part of documentation generation. Flake8 is listed in requirements; use `python -m flake8` if installed.\n\n## Production\nNo verified frontend build command or production hosting provider was found. README recommends a WSGI server such as Gunicorn instead of Flask development server. Dockerfile uses Python 3.10 slim. Production requires strong secret values, HTTPS, restricted CORS, real mail/storage/database, migrations, model assets, observability, and independently managed Redis/worker.\n\n## Environment variables (names only)\n'''+', '.join(f'`{v}`' for v in env)+'''\n\nNames are from `.env.example`; not every variable is used by every run. Never copy actual `.env` values into documentation.\n'''
security_doc='''# Security and Code Audit\n\n## Scope\nThis is a source-based review, not a penetration test, dependency scan or deployment configuration review. Severity describes code/config risk, conditional on deployment. No secrets or `.env` values are reproduced.\n\n## Findings\n| Severity | Evidence | Risk | Recommendation |\n|---|---|---|---|\n| High, conditional | `app.py` refuses normal startup without `GEMINI_API_KEY` even when an operator may not use Gemini | Unrelated app features become unavailable due to optional provider credential | Initialize provider lazily; disable only AI endpoint with explicit readiness status |\n| High, deployment | `auth_utils.py` uses a fallback JWT secret if `JWT_SECRET` absent | Known/default signing key could allow forged tokens if deployed unchanged | Fail startup in production when missing; rotate keys and validate expiry/issuer/audience |\n| Medium | `backend/config/settings.py` declares `ENABLE_*` values but no code consumers found | Operators may believe features are controlled when these flags do nothing | Wire each flag to routes/UI or remove misleading settings; test flag-off behavior |\n| Medium | Multiple token systems (`auth_utils`, Flask-JWT-Extended, service auth) | Inconsistent validation, refresh, role and revocation behavior | Standardize auth contract and audit route-by-route protection |\n| Medium | Broad exception handlers in some routes serialize exception text | Internal diagnostics may leak through API responses | Return stable generic error IDs; log details server-side |\n| Medium | Direct `db.create_all()` at app startup plus migration tree | Schema changes can be unmanaged or deployment startup may race | Run migrations as release step; avoid implicit production schema changes |\n| Medium, agronomic safety | Model scores may be uncalibrated; frontend previously labeled scores >=40% as disease with static severity/treatment | False positive could prompt unnecessary chemical use | UI now marks under-70% or close competing scores uncertain; calibrate using independent field data; never infer severity from class label |\n| Low/Medium, varies by route | Many feature modules have different decorators and input validation patterns | Authorization or validation gaps possible on a route not guarded consistently | Build endpoint-level auth/validation matrix; add integration tests for every write route |\n\n## Controls visible in source\nWerkzeug password hashing is used in User; ORM queries reduce raw SQL construction risk; CORS and Flask-Limiter are configured; input validation/sanitization utilities, audit middleware and environment-based secrets exist. Coverage and production configuration must still be verified.\n\n## Checks not established\nNo dependency vulnerability scanner was run. XSS/CSRF/injection safety cannot be certified globally from a quick scan. Cookie attributes, file ownership checks, upload scanning, CSP, secure headers, production debug status, all-route authorization and external API TLS handling require endpoint/deployment-specific review.\n'''
devops='''# Deployment and DevOps\n\n## Docker\n`Dockerfile` starts from `python:3.10-slim`, installs gcc, installs `requirements.txt`, copies repository and runs `python app.py` on port 5000. It uses Flask development entry point; for production replace with a production WSGI/Socket.IO-compatible server configuration.\n\n`docker-compose.yml` defines Redis 7, MailHog, Flask backend, Celery worker, persistent Redis and uploads volumes. The worker command is `celery -A backend.celery_app worker --loglevel=info`. Compose mounts source into `/app`, appropriate for development but not an immutable production image.\n\n## CI/CD and hosting\n`.github/workflows/` contains issue/PR automation such as labels/assignee actions. A deployment workflow/hosting provider was not found in the scanned files. Do not infer CI build, release or production domain.\n\n## Deployment checklist\n- Choose and configure production database; apply migrations intentionally.\n- Provide strong `SECRET_KEY`, `JWT_SECRET`, provider keys and SMTP/storage credentials through secret manager.\n- Use HTTPS, restrictive CORS, secure cookies, rate limits and non-debug server settings.\n- Include model bundles/class metadata in image/artifact storage and verify readiness.\n- Run Redis, Celery worker and Socket.IO support if required by enabled journeys.\n- Persist uploads outside ephemeral container and enforce access controls.\n- Add health checks, logs, error monitoring, backups and rollback plan.\n- Confirm normal startup does not require unused optional integrations.\n'''
troubleshoot='''# Troubleshooting\n\n| Symptom | Likely cause | What to check |\n|---|---|---|\n| App startup reports missing `GEMINI_API_KEY` | Startup currently requires Gemini outside tests | Set a key in local `.env`, or adjust optional-service initialization for a future source change |\n| Crop prediction unavailable | Crop checkpoint/label encoder missing or version manager cannot load | Verify `crop_recommendation/model/` or configured model registry artifacts and logs |\n| Yield page returns 503 | `crop_yield_model_bundle.joblib` absent/invalid | Follow message: run notebook export cells; ensure bundle has model, encoders, scaler and feature schema; restart app |\n| Disease image endpoint returns 503 | Plant disease checkpoint or class metadata missing | Confirm `Disease prediction/plant_disease_model.pth` and `plant_disease_classes.json` |\n| Disease result marked uncertain | Raw model score below conservative UI gate or top candidates too close | Retake clear close-up in natural light; do not use result alone for treatment |\n| Async tasks stay pending | Redis/broker or Celery worker is not running/configured | Inspect Redis URL, worker logs, task ID and result backend |\n| Email verification not delivered | SMTP settings missing or MailHog/SMTP unavailable | Check configured mail server/port and local MailHog UI if using Compose |\n| API returns 401/403 | Missing/invalid token or insufficient role; auth systems vary | Check endpoint decorator, token issuer and Authorization format; never paste token into chat |\n| DB migration/schema error | Database URL mismatch or unapplied migration | Check active `DATABASE_URL`, migration history, backups; apply migrations deliberately |\n| External weather/AI/translation call fails | Key, URL, network or quota missing | Check variable names and service health without exposing credentials |\n| Static page 404 | Wrong route/path or missing asset | Check root static catch-all, filename case, script/style references and browser network tab |\n'''
interview='''# Interview Preparation\n\n## Two-minute introduction\n“AgroZen is a multi-page smart agriculture web application. Its main backend is Flask, with feature Blueprints and browser pages written in HTML, CSS and JavaScript. It offers crop recommendation, fertilizer guidance, yield prediction, plant disease image classification, and broader farmer services such as weather, irrigation, markets and community workflows. SQLAlchemy stores structured records, and Flask-Migrate manages schema changes. Selected longer tasks use Celery and Redis. I focus on explaining verified flows: a browser request is validated by Flask, routed to a service, processed by a model or database, then returned as HTML or JSON. Some modules require model artifacts or external credentials, and the disease score is not a calibrated probability, so I communicate those limits clearly.”\n\n## Five-minute structure\n1. Problem and users (45 sec).\n2. Architecture: browser → Flask route → service/model/database → response (60 sec).\n3. Demonstrate one crop or yield request with validation and model preprocessing (90 sec).\n4. Explain database/auth/async choices (60 sec).\n5. Show tests actually run, model evaluation evidence, limitations and next steps (60 sec).\n\n## 50 project-grounded questions and answer guides\n'''
qas=[
('What problem does AgroZen address?','It collects selected crop guidance and farmer services into one web entry point; it does not replace local agronomists.'),('What is the main backend entry point?','`app.py`, which loads configuration/extensions and registers direct routes and Blueprints.'),('What is a Blueprint?','A Flask grouping for related routes; registration can add a URL prefix.'),('Is the frontend React?','No main React app was verified; the main UI is multi-page HTML/CSS/JS.'),('What does GET mean?','Ask the server to retrieve a page or information.'),('What does POST mean?','Send data or request an action; endpoint semantics are defined by handler.'),('What is an API?','A structured contract for browser and server messages.'),('How does crop prediction work?','Form POST, required/range checks, ordered feature DataFrame, model inference, label decode and result template.'),('What inputs does crop prediction accept?','N, P, K, temperature, humidity, pH and rainfall in the crop route.'),('Why use a label encoder?','To map text crop labels to integers during training and back for output.'),('What is model inference?','Using a trained model to estimate an output for new input.'),('What is yield prediction’s key constraint?','Feature encoding/scaling and order must match training; bundle is required.'),('What happens if yield bundle is missing?','Service fails initialization; yield route returns 503 with readiness info.'),('How does disease classification work?','Base64 image decoded, resized, RGB tensor made in [0,1], CNN returns logits and softmax scores.'),('Is 60% disease confidence a 60% real-world probability?','No. It is an uncalibrated model score unless calibration has been separately validated.'),('Does the classifier measure disease severity?','No, class label does not quantify severity; UI now calls it typical disease impact or not assessed.'),('Why show alternatives?','They reveal competing labels and can help identify uncertain outputs.'),('What is SQLAlchemy?','ORM that maps Python model classes to relational tables and queries.'),('What is a migration?','Versioned change to database schema.'),('What is a transaction?','A group of database writes committed together or rolled back on failure.'),('Which database is used?','Development defaults to SQLite; environment may configure another DB.'),('What is a foreign key?','A column that references a row in another table.'),('What is authentication?','Verifying a user identity.'),('What is authorization?','Checking which action that identity may perform.'),('How are passwords stored?','Werkzeug password hashes are stored, not plaintext.'),('What is JWT?','A signed token carrying claims such as identity/expiry; server verifies it.'),('Does every route require login?','No; inspect decorators per endpoint. Some routes are public and auth systems vary.'),('What is RBAC?','Role-based access control, where role grants or denies actions.'),('What is Celery used for?','Background task processing outside the web request.'),('Why Redis?','Configured as Celery broker/result backend and cache option.'),('What is polling?','Browser repeatedly asks a task status endpoint using a task ID.'),('What is Socket.IO?','Realtime event transport used where server/client handlers are wired.'),('What is CORS?','Browser rule controlling which origins may call an API cross-origin.'),('Why validate on the server?','Browser checks can be bypassed, so server is the trust boundary.'),('What does rate limiting do?','Caps request frequency to reduce abuse/load.'),('What is the purpose of audit logs?','Record security-sensitive actions for traceability.'),('Where are secrets stored?','Environment configuration; never commit or expose actual values.'),('What is the major startup configuration caveat?','Normal app startup requires Gemini key currently.'),('Are feature flags effective?','Flags are defined, but no consumers found; presently they appear non-operative.'),('What makes an integration optional?','Its provider credentials/network and code path must be configured.'),('What tests exist?','Pytest suites and security-related tests; verify exact coverage before claims.'),('How evaluate classification?','Independent holdout, per-class precision/recall/F1, confusion matrix and field generalization.'),('How evaluate regression?','MAE/RMSE/R² with target units, baselines and subgroup error.'),('How protect file uploads?','Check type/size/content, safe names, storage isolation, ownership authorization and path safety.'),('What is XSS?','Attacker-controlled content running as script in another user’s browser; escape/render safely.'),('What is CSRF?','A browser tricked into sending an authenticated state-changing request; use SameSite/CSRF defenses.'),('What is the known JWT concern?','Legacy helper has a fallback secret; production must require a unique secret.'),('What do Docker services run?','Flask app, Redis, MailHog and Celery worker.'),('Is there a frontend build step?','No main frontend build script detected; npm scripts launch optional Node server.'),('Name a technical limitation.','Large modular repository includes partially integrated modules; demonstrate route→service→DB/model path.'),('What would you improve first?','Standardize auth, make flags effective, remove optional-key startup coupling, add calibrated field-based ML evaluation and route integration tests.')]
for i,(q,a) in enumerate(qas,1): interview+=f'\n{i}. **{q}** {a}\n'
interview+='''\n## Interview honesty rule\nSay “implemented in source” only if you can point to the page, active route, service/model, persistence path and a successful demo. Say “needs configuration” for external services/model artifacts. Say “not verified” for production status or unmeasured model quality.\n'''
